  VALUES 
    (131::BIGINT, 'Lo más fácil para pasar, 3 exposiciones y un trabajo final, que si no la caga es 100 fijo y tuvimos como 4 semanas sin clases y si había clases son de como mucho una hora si no hay exposiciones'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2026-07-14T00:00:00+00:00'::TIMESTAMPTZ, '8a89d05a3ec0a566aaa03b653b359bf1b25ef5c6d57c142e850ad524287dd871'::TEXT, ARRAY[1004]::BIGINT[]),
    (131::BIGINT, 'El peak de la escuela.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2025-12-05T00:00:00+00:00'::TIMESTAMPTZ, '445c8547049eb7266b3cf4f9fd95e2d2241c42416b1abbbfd07f18906aab499b'::TEXT, ARRAY[1004]::BIGINT[]),
    (131::BIGINT, 'Muy buena profe, el curso se pasa solo'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-11-05T00:00:00+00:00'::TIMESTAMPTZ, '072d533e67cb8f8ff1d34e6ca96d69b4c3455606fc867fcce1d5da75c04179bf'::TEXT, ARRAY[1004]::BIGINT[]),
    (131::BIGINT, 'Es buena profe para pasar el curso fácil, es relajada para calificar y no pide muchos trabajos. Sin embargo, las clases son aburridas, del tipo que solo lee la presentación y parece que no espera que le hagan consultas. Mala forma de dar la clase para ser virtual, poco participativa.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'Asistencia obligatoria', 'Muchos proyectos grupales']::TEXT[], '2025-10-14T00:00:00+00:00'::TIMESTAMPTZ, '1248c3fa96210fccb72625d5e5225eead5492ccc76995448cfff758b90499e6c'::TEXT, ARRAY[1004]::BIGINT[]),
    (131::BIGINT, 'Es como la señorita Miel, dulce, explica bien, sus clases son super relajadas, no pide que se encienda la cámara, no califica duro, a veces deja un documental para que lo veamos en horario de clase. Es decir, ella es un sol. Si puede matricular con ella no lo dude.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-06-23T00:00:00+00:00'::TIMESTAMPTZ, '86d61a7917f16484039f3bec4a0404d5862418b1b947f874a83283259766c54b'::TEXT, ARRAY[1004]::BIGINT[]),
    (131::BIGINT, 'La materia del curso se me hizo un poco aburrida, es muy parecida a una clase de estudios sociales. Sin embargo, la profe hace las clases bastante interesantes y los trabajos no son complicados y ella no califica duro, la verdad tomaría la clase de nuevo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2023-01-20T00:00:00+00:00'::TIMESTAMPTZ, '55219787d9d33cc78a373894ea9a5a7c15dc9ff3a2f8628a6b46ed9ddd83f2a0'::TEXT, ARRAY[1004]::BIGINT[]),
    (131::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2022-11-10T00:00:00+00:00'::TIMESTAMPTZ, '5505a72c80619630ca844763d108c1f842fc42a1645d63498d8ebe6793407ab3'::TEXT, ARRAY[1004]::BIGINT[]),
    (131::BIGINT, 'Yo lo llevé en verano virtual pero el curso con la profe es demasiado bueno, hace que las clases sean muy interesantes y el curso no es para nada complicado con ella.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Aspectos de calificación claros', 'Muchos proyectos grupales']::TEXT[], '2022-01-25T00:00:00+00:00'::TIMESTAMPTZ, '07a402397f02f12c13db513e9adb2a93ac6bf3bceab36958d5309ab95f41813d'::TEXT, ARRAY[1004]::BIGINT[]),
    (131::BIGINT, 'Las clases y la temática del curso son sumamente aburridas pero esta profe hace el curso sumamente ameno. Con sólo cumplir con los trabajos se pasa con una nota rajada. Si quiere pasar el curso sin tener que palmarla tanto esta es una opción genial'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-11-23T00:00:00+00:00'::TIMESTAMPTZ, '616ea53a9adbebfbf554a885bc21c30553734a04e5c3b56d8f55e4f77775348e'::TEXT, ARRAY[1004]::BIGINT[]),
    (131::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Respetado por los estudiantes', 'Aspectos de calificación claros']::TEXT[], '2021-02-15T00:00:00+00:00'::TIMESTAMPTZ, '56ad4c1742a9404e1940528d1aa717a4e161a0a03da1b0b7eefa0fae1a5ab138'::TEXT, ARRAY[1004]::BIGINT[]),
    (131::BIGINT, 'Es muy buena con los estudiantes, los trabajos son bastante fáciles y califica suave. En modalidad virtual fueron pocas clases.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-26T00:00:00+00:00'::TIMESTAMPTZ, '78fe21f44118276eb97de6955e4daf683b627ddb6647af8e23fd3821bfa50532'::TEXT, ARRAY[1004]::BIGINT[]),
    (131::BIGINT, 'Un amor, super chill, super recomendada, super todo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-13T00:00:00+00:00'::TIMESTAMPTZ, '8223706ce3cbd1b9e97c399a8fd6d9771ee5ec2e4a325a3cc6ff8aed289faadb'::TEXT, ARRAY[1004]::BIGINT[]),
    (131::BIGINT, 'Se pasa super fácil con esta profesora. Al menos en este primer semestre virtual, con tener al día las tareas y cumplir con los parciales es suficiente para pasar el curso con una buena nota. En virtual las clases son súper cortas.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Pocos exámenes', 'Tomaría su clase nuevamente']::TEXT[], '2020-07-21T00:00:00+00:00'::TIMESTAMPTZ, 'ebdbada22633d3391a67bb7d188b64dd25e5838c74189961e34bd456df45c1a1'::TEXT, ARRAY[559]::BIGINT[]),
    (131::BIGINT, 'El único problema es que sus clases se vuelven muy... MUY aburridas, sin embargo logra enseñar de manera correcta, también incita al trabajo en grupo'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchos proyectos grupales']::TEXT[], '2020-07-16T00:00:00+00:00'::TIMESTAMPTZ, '50a18524a09d7d62a1027f7397a2a158852d5a9c42303a910ab78ea040484269'::TEXT, ARRAY[559]::BIGINT[]),
    (131::BIGINT, 'El curso es aburrido, la profe es también algo aburrida. La salvada es que casi no dejan trabajos para la casa entonces se pasa fácil.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-25T00:00:00+00:00'::TIMESTAMPTZ, '1cba831560216cd6f1334daf8a2a3688b8a92dff480f2ee2b3219ab315f22c44'::TEXT, ARRAY[1004]::BIGINT[]),
    (131::BIGINT, 'Pues casi no deja evaluaciones y las que deja son muy cortas y faciles. En clase se hacen trabajos en grupo y despues ella habla. Muy facil y muy linda persona.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-22T00:00:00+00:00'::TIMESTAMPTZ, '04c6bd4f30e170cf1720a24d24d37b53efa85213707ed7ee180e1f8be3e95896'::TEXT, ARRAY[1357]::BIGINT[]),
    (131::BIGINT, 'Es muy linda persona y las clases son muy fáciles. Solo deja cuestionarios que se hacen en grupos en la clase, los exámenes son fáciles y deja muy pocos trabajos cortos.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-19T00:00:00+00:00'::TIMESTAMPTZ, '03e60ad22a594512d0023cf8c8460857e78ddaa569c64e00e5cca299e58dff49'::TEXT, ARRAY[559]::BIGINT[]),
    (131::BIGINT, 'Un amor de persona, los trabajos son grupales. Haga todo los trabajos en clase, los exámenes súper fáciles, en pareja por lo general.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-15T00:00:00+00:00'::TIMESTAMPTZ, 'ee7554f95481d847584ed90d56485c00b5e4d450c87564ef2b97d59dc75dce69'::TEXT, ARRAY[559]::BIGINT[]),
    (131::BIGINT, 'Está hecha de amor, es súper buena gente y chill'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2019-06-08T00:00:00+00:00'::TIMESTAMPTZ, '400c3719fe78ffedebd7bf0ccc758eb881e683b13815c91d38b8322148677107'::TEXT, ARRAY[559]::BIGINT[]),
    (131::BIGINT, 'No dude en matricular con ella. El curso es fácil en sí y no requiere de horas fuera de clase. No deja tareas e hicimos solamente 1 examen en todo el semestre y era en parejas. Es super considerada y buena gente.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-05-24T00:00:00+00:00'::TIMESTAMPTZ, 'f7629eb16186086147cc784849f68d37285dc87fb6d1b9e98fd48d3172aa3d1c'::TEXT, ARRAY[559]::BIGINT[]),
    (131::BIGINT, 'El amor hecho persona, sólo dan ganas de abrazarla. Hace el curso súper fácil y se aprende montones, 100% recomendada.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-12-13T00:00:00+00:00'::TIMESTAMPTZ, 'cf2fb1871ec022bec4f56698da8b37684855e6bb88bdb38ab237139ed224a198'::TEXT, ARRAY[1004]::BIGINT[]),
    (131::BIGINT, 'Es un amor de profesora, súper comprensiva y pura vida.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-27T00:00:00+00:00'::TIMESTAMPTZ, 'a20ee32463ff11341d6bf81bcdfa8463be83bdeb5118606ae0288b71580dad40'::TEXT, ARRAY[1004]::BIGINT[]),
