    (131::BIGINT, 'Excelente profesora, las clases se hacen menos aburridas a pesar de ser Ambiente Humano, las clases se hacen cortas, la recomiendo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2018-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'e0734ea57909bc7539035fac9d158d2f2856b06b535dc1d70bfc07877312876b'::TEXT, ARRAY[628]::BIGINT[]),
    (131::BIGINT, 'Ella es la mejor, el curso se pasa solo, los examenes son para la casa, deja actividades en clase pero si falta da oportunidad de llevarlas despues'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'dc2dc52d68402c906e61b8cc2ff6dbea43c459946f2c5e8cd51c7df96f1593cd'::TEXT, ARRAY[628]::BIGINT[]),
    (131::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-22T00:00:00+00:00'::TIMESTAMPTZ, '1898c74b2d969233098a15c07e2094fa8aba15076476a042532a42e9111f6f96'::TEXT, ARRAY[628]::BIGINT[]),
    (131::BIGINT, 'Las clases son muuuy aburridas, pero va a pasar de fijo. La profe es muy cosi'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-16T00:00:00+00:00'::TIMESTAMPTZ, 'ae4b18008d660967e8d839f70f48bdf2302ea2551ce4d7646c9bf6c5e17b48da'::TEXT, ARRAY[628]::BIGINT[]),
    (131::BIGINT, 'La mejor, es un amor, hace que todo sea sencillo para que el curso no pese para nada en el semestre, todo se hace en clase y es muy fácil'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-02-04T00:00:00+00:00'::TIMESTAMPTZ, '4dfbb140e757bd53df1f56e398fd07494f9a24cc73db77fefaaa7ac38e5a7b0e'::TEXT, ARRAY[1004]::BIGINT[]),
    (131::BIGINT, 'Un curso muy sencillo. No hay que leer en casa, poquitas tareas, trabajos muy fáciles. La profesora es súper amable, respetuosa. Haces como 3 o 4 exposiciones. Ves videos.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2018-01-22T00:00:00+00:00'::TIMESTAMPTZ, '5ca268ffbe6b0d09783a2472712ad84af20f898ca8dcf582bb8afdd65989aa73'::TEXT, ARRAY[1004]::BIGINT[]),
    (131::BIGINT, 'Es un amor, hace trabajos fáciles y directo al punto. Casi no deja tareas. Nisiquiera hay que ponerle mucha atención, y ella es muy paciente aunque uno no venga con motivación. De fijo matricularla jajaja'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-01-17T00:00:00+00:00'::TIMESTAMPTZ, 'bce80b6bd3f78ad7d86d155027dfcad35b97db40c1c07188c198e88519a8a222'::TEXT, ARRAY[628]::BIGINT[]),
    (131::BIGINT, 'Excelente profe. El curso se hace fácil con ella y aún más si le ponen atención y no van a dormir como yo xD. Los trabajos se hacen en clase y en grupo por lo que son fáciles. Califica suave así que manda si no pasan. Muy buena persona. Asistencia obligatoria.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-12-06T00:00:00+00:00'::TIMESTAMPTZ, 'fc17ad7314bb30a9d18889ad2199851d6b2e1d0e4128cb25bc7d972c7a7b0ca7'::TEXT, ARRAY[628]::BIGINT[]),
    (131::BIGINT, 'Excelente Profesora explica claro y conciso. Los trabajos son muy fáciles y cortos. Sin duda la mejor opción.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes']::TEXT[], '2017-11-22T00:00:00+00:00'::TIMESTAMPTZ, '8c49a1d17a80f80191e5ec9f4d1e485a4db688a6f578fbefeecea8af78090ab1'::TEXT, ARRAY[628]::BIGINT[]),
    (131::BIGINT, 'Es muy linda, siempre se sale temprano, los trabajos son fáciles'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-27T00:00:00+00:00'::TIMESTAMPTZ, '4fcc2fd89b50d62b454331b1f5abec487044445d43e91c94adc2eae67c7bd09d'::TEXT, ARRAY[1004]::BIGINT[]),
    (131::BIGINT, 'Es súper dulce y buena gente, el curso se pasa solo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-22T00:00:00+00:00'::TIMESTAMPTZ, '38d90c2ad9c6f3f426286f21fd6922b72d292fc2a1b35aea7de52a15d2993a6b'::TEXT, ARRAY[559]::BIGINT[]),
    (131::BIGINT, 'Clases un poco aburridas pero nada del otro mundo. Es un amor de profe, los exámenes los hace en parejas a veces y hace un resumen antes del examen final. Se pasa fácil, apenas para subir el ponderado'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-15T00:00:00+00:00'::TIMESTAMPTZ, '0188583e528a130d12145b3d3bb83941acf3ab6a775319b0ab0f82c721fec58c'::TEXT, ARRAY[559]::BIGINT[]),
    (131::BIGINT, 'Muy agradable, la materia se pasa fácil pues las preguntas de los exámenes son muy generales entonces lo que sea que escriba esta bien. Clases un poco aburridas'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-15T00:00:00+00:00'::TIMESTAMPTZ, 'b36d52d92aa4a3f7f1764b95c08908f41250623b5635a6a0d84c131b571496df'::TEXT, ARRAY[559]::BIGINT[]),
    (131::BIGINT, 'Se pasa muy fácil, y sin leer ni una sola lectura, obviamente si uno las lee entiende mucho más y le va mejor pero no es indispensable, en su clase se hacen cuestionarios en grupos relacionados con las lecturas pero teniendolas a mano. Antes de cada examen da un resumen de la materia,'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-14T00:00:00+00:00'::TIMESTAMPTZ, 'e8140107f2206b130d84429a82b379c05ba3406cca4cc66a60f008ee55e8703a'::TEXT, ARRAY[559]::BIGINT[]),
    (131::BIGINT, 'Es muy vaga, no deja tareas, la clase es hacer cuestionarios, no explica nada'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-13T00:00:00+00:00'::TIMESTAMPTZ, '1252f7a6dbad2a408e6fbad8f2606272f42cbd097c4a8ca7a5653da67a8acd4c'::TEXT, ARRAY[559]::BIGINT[]),
    (131::BIGINT, 'Muy buena persona, todas las lecturas se hacen en clase, de modo que no quedan de tarea. Super dulce'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2017-05-05T00:00:00+00:00'::TIMESTAMPTZ, 'aef07b0c3d0f9ba182d1e065a0ef4391a5338b9cf1105d6cb03c937461e83b54'::TEXT, ARRAY[559]::BIGINT[]),
    (131::BIGINT, 'Se sale de clases antes de tiempo, el proyecto final es facil y los exámenes tambien es super buena profe'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-11-30T00:00:00+00:00'::TIMESTAMPTZ, '9ca62eafb54b54a76bd723111f2b415517bfd64b48c25662bf3d2ffeaebe26ea'::TEXT, ARRAY[628]::BIGINT[]),
    (131::BIGINT, 'Es súper buena persona. Los trabajos de clases solo son responder preguntas. Exámenes para la casa y en el proyecto no es muy exigente'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-11-24T00:00:00+00:00'::TIMESTAMPTZ, 'b425e04788dab16632728d9f1b6ef7168b17b64c33cc4fb243dc62696529a763'::TEXT, ARRAY[628]::BIGINT[]),
    (131::BIGINT, 'Si mete algún curso con Mairim ya lo ganó ¡Jajaja!'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-27T00:00:00+00:00'::TIMESTAMPTZ, '4c872f76e35d328d3ced81b413f36580acdb4a47f1097f05d5cb62bfbf11729b'::TEXT, ARRAY[628]::BIGINT[]),
    (131::BIGINT, 'Muy buena persona. Hace que el curso no sea tan asco. Deja trabajos en clase muy sencillos. Deja los examenes para la casa y algunos ensayos y lecturas tambien. Es muy buena explicando y se sale temprano cuando es necesario.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2016-06-24T00:00:00+00:00'::TIMESTAMPTZ, '48d5a9de1bd725cffd2c0718a29da580fd79b421fdd6230d23c65663161b7a57'::TEXT, ARRAY[628]::BIGINT[]),
    (131::BIGINT, 'Es muy buena nota y muchas veces salimos antes de la hora. Pone mucho trabajo en clase pero son puntos ganados. Explica las diapositivas y de paso las sube al TDigital.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2016-06-07T00:00:00+00:00'::TIMESTAMPTZ, 'dccc02a77140c3c32d0825e86f870ce08285526ad7fd79e90ed68ab467e11fe4'::TEXT, ARRAY[628]::BIGINT[]),
    (131::BIGINT, 'Es una excelente persona, muy comprensiva y califica super suave. Eso sí, las clases son demasiado aburridas, además tarda bastante en entregar los exámenes. Pero la recomiendo mucho'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-06T00:00:00+00:00'::TIMESTAMPTZ, '40aa1a27866ccb5298e93dccd9caee9fec3df8189f4fad1e3340e8bb6e72ee7e'::TEXT, ARRAY[628]::BIGINT[]),
    (131::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes']::TEXT[], '2016-02-04T00:00:00+00:00'::TIMESTAMPTZ, 'a1e9f45ebe641919ebb8dcdacf6c5b2451c25b508432c7182308bc73892b435a'::TEXT, ARRAY[559]::BIGINT[]),
    (131::BIGINT, 'De las mejores profes que he tenido, muy buena gente y cariñosa. En lo academico no exige mucho y los trabajos son sencillos.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-28T00:00:00+00:00'::TIMESTAMPTZ, '66c8f103684dd133bd87cc61e2b9b37ba5d01ae79594807cc9c707de5ead500f'::TEXT, ARRAY[559]::BIGINT[]),
    (131::BIGINT, 'La profe es un éxito, explica muy bien, las clases son entretenidas, al menos no las hace aburridas, la profe es muy "buena gente" y cariñosa, y hace el curso llevadero. Califica bonito.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-23T00:00:00+00:00'::TIMESTAMPTZ, '4afa80879e4f778cd0b47a9fbc7b35934d676791f24f04574d8bdcc17d80f4b8'::TEXT, ARRAY[628]::BIGINT[]),
    (131::BIGINT, 'Buena profe. No se le da la tecnología, no espere que conteste correos. La mayoría de los trabajos se hacen en clase. Explica con diapositivas que luego comparte, igual que las lecturas. Se pasa fácil con ella. No requiere tanto tiempo como otros profesores. Es muy dulce. Recomendada'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-21T00:00:00+00:00'::TIMESTAMPTZ, 'f3790dfed9a5d7b444411486417bb13ade27ed7b5342d58a7a70726de4f91fe2'::TEXT, ARRAY[628]::BIGINT[]),
    (131::BIGINT, 'Excelente profesora, muy buena gente'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-05T00:00:00+00:00'::TIMESTAMPTZ, '78cd30a65092378bbb486ccf3789a489efe4d69ad929b5a541c8cacde3273d5f'::TEXT, ARRAY[628]::BIGINT[]),
    (131::BIGINT, 'Es buena gente, es fácil y la mayoría de los trabajos se hacen en clase.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-07-03T00:00:00+00:00'::TIMESTAMPTZ, 'bd14777898726625172e09fb675bbe05414f96d74b39945ce9b491b80d05975d'::TEXT, ARRAY[559]::BIGINT[]),
    (131::BIGINT, 'Un amor de profe en todos los sentidos'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-28T00:00:00+00:00'::TIMESTAMPTZ, 'ebfeb5b55e5e2f4fc9b198574ff76b4b2c791ab2f00e8b5e8da7c84bf31ed5c3'::TEXT, ARRAY[628]::BIGINT[]),
    (131::BIGINT, 'super recomendada, es un amor de persona'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'e2e1a00fe3ddeb9cb5443b3670d3c871e68ea65109adda21209109f96b341048'::TEXT, ARRAY[559]::BIGINT[]),
    (131::BIGINT, 'Es un amor de persona, super flexible a la hora de entregar tareas, trabajos etc. Es facil entenderle y los trabajos que dejan son muy sencillos. Además no califica rudo'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-05-10T00:00:00+00:00'::TIMESTAMPTZ, '1ab5c5d8a83f271157aadd9d273adec1eb2eccb4adcbe37ae0e0dd60e8b72a72'::TEXT, ARRAY[559]::BIGINT[]),
    (131::BIGINT, 'Un amor de profe, en verano nos llevaba café y galletas por el frio. Califica bien y es muy clara.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-24T00:00:00+00:00'::TIMESTAMPTZ, 'bed800445fa580cb30ff7bee7ffe38fd34eb652d39410b18f321bcfdff27859c'::TEXT, ARRAY[1004]::BIGINT[]),
    (131::BIGINT, 'Excelente profe. Muy cariñosa y siempre trata de ayudar. Es clara explicando la materia y se aprende bien. Muy flexible a la hora de consulta y tardías/ausencias.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-17T00:00:00+00:00'::TIMESTAMPTZ, '2fee2b0fa66b3e89bcc81a6619cc1542bb835ce56ff6c5f19b81956fd43856ab'::TEXT, ARRAY[559]::BIGINT[]),
    (131::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-13T00:00:00+00:00'::TIMESTAMPTZ, 'ef538c10f26b11287ad453ff0d6e020f8a05bd0a49bcfc0946bc9a2c4aa86f6a'::TEXT, ARRAY[559]::BIGINT[]),
    (131::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-08T00:00:00+00:00'::TIMESTAMPTZ, 'd90067ac89a7906f408c7bafd3d1edab49aad6e43545a2dc60d8270d4dda3f33'::TEXT, ARRAY[559]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
